let communitiesTab="all",joinedIds=new Set,communitySearch="";const COMMUNITIES_PAGE_SIZE=10;let communitiesPage={all:1,mine:1};async function loadJoinedIds(){if(!currentSession)return void(joinedIds=new Set);const{data:e}=await sb.from("community_members").select("community_id").eq("user_id",currentSession.user.id);joinedIds=new Set((e||[]).map(e=>e.community_id))}function switchCommunitiesTab(e){e!==communitiesTab&&(communitiesTab=e,communitiesPage[e]=1,document.getElementById("ctab-all").classList.toggle("active","all"===e),document.getElementById("ctab-mine").classList.toggle("active","mine"===e),renderList())}function gotoCommunitiesPage(e){communitiesPage[communitiesTab]=e,renderList(),document.getElementById("communities-list")?.scrollIntoView({block:"start",behavior:"smooth"})}async function renderList(){const e=document.getElementById("communities-list");if(e.innerHTML=skeletonFeedHtml(),"mine"===communitiesTab&&!currentSession)return void(e.innerHTML='<div class="post-login-gate" style="border-top:none;">You need an account to post. <a href="signup.html">Create an account</a> — it takes a minute.</div>');const n=communitySearch.trim(),t=communitiesPage[communitiesTab];let i,o;if("mine"===communitiesTab){const{data:s,error:m}=await sb.from("community_members").select("community:communities(*)").eq("user_id",currentSession.user.id).order("joined_at",{ascending:!1});if(m)return void(e.innerHTML=`<div class="errmsg">${esc(m.message)}</div>`);let c=(s||[]).map(e=>e.community).filter(Boolean);if(n){const e=n.toLowerCase();c=c.filter(n=>n.name.toLowerCase().includes(e)||(n.description||"").toLowerCase().includes(e))}o=c.length,i=c.slice(10*(t-1),10*t)}else{let s=sb.from("communities").select("*",{count:"exact"});n&&(s=s.or(`name.ilike.%${n}%,description.ilike.%${n}%`));const{data:m,error:c,count:a}=await s.order("member_count",{ascending:!1}).order("created_at",{ascending:!1}).range(10*(t-1),10*t-1);if(c)return void(e.innerHTML=`<div class="errmsg">${esc(c.message)}</div>`);i=m||[],o=a||0}if(!i.length)return void(e.innerHTML=n?`<div id="feed-empty">No communities found for &ldquo;${esc(n)}&rdquo;.</div>`:"mine"===communitiesTab?'<div id="feed-empty">You haven\'t joined any communities yet.</div>':'<div id="feed-empty">No communities yet. Be the first to create one.</div>');const s=Math.max(1,Math.ceil(o/10));e.innerHTML='<div class="comm-list">'+i.map(e=>communityRowHtml(e,"mine"===communitiesTab||joinedIds.has(e.id))).join("")+"</div>"+pagerHtml(t,s,"gotoCommunitiesPage")}function communityRowHtml(e,n){const t=n?`<button class="who-follow-btn comm-joined-btn" onclick="event.preventDefault();communityToggleJoin('${e.id}', this, true)">Joined</button>`:`<button class="who-follow-btn" onclick="event.preventDefault();communityToggleJoin('${e.id}', this, false)">Join</button>`;return`\n    <a class="who-row comm-row" href="${communityUrl(e.slug)}">\n      <span class="comm-avatar">${communityAvatarInner(e)}</span>\n      <span class="who-row-txt">\n        <span class="who-row-name">${esc(e.name)}</span>\n        ${e.description?`<span class="comm-desc">${esc(e.description)}</span>`:""}\n        <span class="who-row-handle">${fmtCount(e.member_count)} member${1===e.member_count?"":"s"}</span>\n      </span>\n      ${t}\n    </a>`}function onCommunityMembershipChanged(e,n){n?joinedIds.add(e):joinedIds.delete(e),"mine"===communitiesTab&&renderList()}let _searchDebounce=null;function wireCommunitySearch(){const e=document.getElementById("comm-search");e&&e.addEventListener("input",()=>{clearTimeout(_searchDebounce),_searchDebounce=setTimeout(()=>{communitySearch=e.value,communitiesPage[communitiesTab]=1,renderList()},250)})}document.addEventListener("DOMContentLoaded",async()=>{"communities"===document.body.dataset.page&&(await authReady,wireCommunitySearch(),await loadJoinedIds(),renderList())});